package local.velo.bridge;
import android.app.*;import android.content.*;import android.os.*;import android.location.*;import java.util.*;import org.json.*;
public final class RouteChoiceTest extends Instrumentation {
 int checks;MainActivity app;void main(Runnable r){runOnMainSync(r);}void check(boolean value,String label)throws Exception{checks++;if(!value)throw new Exception(label);}public void onCreate(Bundle b){super.onCreate(b);start();}
 public void onStart(){Bundle out=new Bundle();Context c=getTargetContext();try{c.stopService(new Intent(c,RideService.class));c.stopService(new Intent(c,DeviceLinkService.class));c.getSharedPreferences("navigation",0).edit().remove("device_address").commit();app=(MainActivity)startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));MainActivity.Place a=new MainActivity.Place("A",33.5504,133.5072),b=new MainActivity.Place("B",33.5506,133.5100),z=new MainActivity.Place("C",33.5531,133.5063);MainActivity.Place[] points={a,b,z};for(MainActivity.Place from:points)for(MainActivity.Place to:points){if(from==to)continue;main(()->{app.newRoute();app.setPoint("from",from);app.setPoint("to",to);});check(app.origin==from&&app.destination==to,"arbitrary origin and destination roles");check(app.routePoints().get(0)==from&&app.routePoints().get(app.routePoints().size()-1)==to,"planning snapshot keeps requested endpoints");check(!app.planning,"selecting points never auto plans");}
 main(()->{app.newRoute();app.setPoint("from",a);app.setPoint("to",z);app.setPoint("via",b);});check(app.routePoints().size()==3&&app.routePoints().get(1)==b,"three points preserve waypoint order");check(app.preview.via.size()==1&&app.preview.to==z,"map shows chosen endpoint and waypoint");main(()->app.setPoint("to",b));check(app.destination==b&&app.via.isEmpty(),"waypoint can become endpoint without duplicate");main(()->app.setPoint("from",z));check(app.origin==z&&app.destination==b,"changing start keeps selected finish");check(new JSONObject(c.getSharedPreferences("navigation",0).getString("destination","{}")).getString("name").equals("B"),"chosen endpoint persisted");
 main(()->{app.pendingPlan=true;app.setPoint("from",a);app.select(true,new MainActivity.Place("当前位置旧定位",34,134));});check(app.origin==a&&!app.pendingPlan&&!app.planning,"late location cannot replace manual origin or trigger planning");main(()->app.newRoute());check(app.origin==null&&app.destination==null&&app.via.isEmpty(),"new route clears old draft points");check(!c.getSharedPreferences("navigation",0).contains("origin")&&!c.getSharedPreferences("navigation",0).contains("destination"),"cleared endpoints stay cleared after restart");
 main(()->{app.setPoint("from",z);app.setPoint("to",a);app.setPoint("via",b);app.plan();});for(int i=0;i<120&&app.planning;i++)Thread.sleep(1000);check(!app.planning&&!app.draftChanged,"actual three point plan succeeds: "+app.lastNote);RouteModel r=RouteStore.route;double[] first=MapMath.point(r,r.x[0],r.y[0]),last=MapMath.point(r,r.x[r.x.length-1],r.y[r.y.length-1]);check(Math.hypot(first[0]-z.lat,first[1]-z.lon)<.0015,"actual route begins at selected C rather than old A");check(Math.hypot(last[0]-a.lat,last[1]-a.lon)<.0015,"actual route ends at selected A rather than previous B");check(r.name.equals("A"),"route uses chosen destination name");main(()->app.plan());for(int i=0;i<120&&app.planning;i++)Thread.sleep(1000);check(app.origin==z&&app.destination==a,"replanning does not silently replace endpoints");out.putString("checks",checks+" explicit endpoint, stale GPS and real route checks passed");finish(Activity.RESULT_OK,out);}catch(Throwable e){out.putString("error",e.toString());finish(Activity.RESULT_CANCELED,out);}}
}
